CREATE TABLE employees (
    id INT,
    name VARCHAR(50),
    department VARCHAR(50),
    salary INT
);
INSERT INTO employees VALUES 
(1, 'Ana', 'AI', 60000),
(2, 'Ravi', 'Backend', 50000),
(3, 'John', 'AI', 65000);

SELECT DISTINCT department FROM employees;

SELECT name, department, salary 
FROM employees 
WHERE (department = 'AI' OR department = 'Backend') AND salary >= 55000;

SELECT name, salary 
FROM employees 
ORDER BY salary DESC, name ASC;
